#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Activate Postgres RLS on the production host (plan 028). Run it once, before the deploy of the RLS release.
# Run with bash: bash infra/k8s/activate-rls-wizard.sh
# It reads and extends ~/.config/cartogra-production/production.env (from production-host-wizard.sh).
#
# Order matters:
#   1. Stages 1-3 before the merge: the roles exist before the new images start (the RLS migrations
#      grant to cartogra_app). The running release still connects as the superuser, so it keeps working.
#   2. Merge. The deploy starts by itself. The new code still connects as the superuser, so RLS has no effect yet.
#   3. Stage 4 after that deploy: apply the new secrets, then restart the services. An old pod
#      that starts with the new secrets breaks, because the old code does not set the tenant.

REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")" && git rev-parse --show-toplevel)
CONF_DIR="$HOME/.config/cartogra-production"
export KUBECONFIG="$HOME/.kube/cartogra-production"
ROLES_SQL=infra/helm/cartogra/charts/postgres/files/bootstrap-roles.sql

# run CMD... echoes a command, then runs it.
run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET" >&2; "$@"; }

# begin ID: on a re-run, offers to skip a stage already finished.
begin() {
  [[ "$(_existing "DONE_$1" || true)" == 1 ]] || return 0
  note "Finished on an earlier run."
  confirm "Run this stage again?"
}
finished() { write_env "DONE_$1" 1; }

# gen KEY CMD...: generates a value once; later runs reuse the saved one.
gen() {
  local key="$1"; shift
  local v; v=$(_existing "$key" || true)
  [[ -n "$v" ]] || v=$("$@")
  write_env "$key" "$v"
}

run_wizard() {

TOTAL_STAGES=5
ENV_FILE="$CONF_DIR/production.env"
if [[ ! -f "$ENV_FILE" ]]; then
  warn "$ENV_FILE not found. It holds the current secrets (production-host-wizard.sh)."
  exit 1
fi
# shellcheck disable=SC1090
set -a; . "$ENV_FILE"; set +a
cd "$REPO"

banner "Activate Postgres RLS on production (plan 028)"

# ──────────────────────────────────────────────────────────────────────────
stage "Preconditions"
if begin pre; then
  run kubectl -n cartogra get pod postgres-0
  if [[ -z "${INTERNAL_TOKEN_KEY:-}" ]]; then
    note "INTERNAL_TOKEN_KEY is not in $ENV_FILE. Read it from the live gateway-secrets."
    INTERNAL_TOKEN_KEY=$(kubectl -n cartogra get secret gateway-secrets \
      -o jsonpath='{.data.INTERNAL_TOKEN_KEY}' | base64 -d || true)
    [[ -z "$INTERNAL_TOKEN_KEY" ]] || write_env INTERNAL_TOKEN_KEY "$INTERNAL_TOKEN_KEY"
  fi
  for k in DB_PASSWORD JWT_SECRET INTERNAL_TOKEN_KEY RESEND_API_KEY ADMIN_PASSWORD CLUSTER_CREDENTIALS_KEY; do
    if [[ -z "${!k:-}" ]]; then
      warn "$k is missing in $ENV_FILE. Stop."
      exit 1
    fi
  done
  step "Make sure that the latest backup is verified (deployment.md, backups)."
  pause "Press Enter once the latest backup is verified"
  finished pre
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Database roles: create cartogra_owner and cartogra_app, move ownership"
if begin roles; then
  gen OWNER_DB_PASSWORD openssl rand -hex 24
  gen APP_DB_PASSWORD openssl rand -hex 24
  warn "Store OWNER_DB_PASSWORD and APP_DB_PASSWORD in your password manager."
  note "They are in $ENV_FILE."
  pause "Press Enter once stored"
  note "This is safe for the running release: it still connects as the superuser."
  confirm "Run $ROLES_SQL on postgres-0 now?" || exit 1
  kubectl -n cartogra exec -i postgres-0 -- sh -c \
    'psql -v ON_ERROR_STOP=1 -U "$(cat /etc/cartogra/secrets/DB_USERNAME)" -d cartogra -v owner_password="$1" -v app_password="$2" -f -' \
    _ "$OWNER_DB_PASSWORD" "$APP_DB_PASSWORD" < "$ROLES_SQL"
  run kubectl -n cartogra exec postgres-0 -- sh -c \
    'psql -U "$(cat /etc/cartogra/secrets/DB_USERNAME)" -d cartogra -c "\du cartogra_*" -c "\dn"'
  step "Expect both roles, and each service schema owned by cartogra_owner."
  pause "Press Enter if that is correct"
  finished roles
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Seal the new secrets (do not apply them yet)"
if begin seal; then
  seal() {
    local ns=$1 name=$2; shift 2
    kubectl -n "$ns" create secret generic "$name" --dry-run=client -o yaml "$@" \
      | kubeseal --format yaml > "infra/k8s/sealed/$name.yaml"
    printf '  %s✓ sealed%s %s/%s\n' "$GREEN" "$RESET" "$ns" "$name"
  }
  DB=(--from-literal=DB_USERNAME=cartogra_app --from-literal=DB_PASSWORD="$APP_DB_PASSWORD"
      --from-literal=FLYWAY_USERNAME=cartogra_owner --from-literal=FLYWAY_PASSWORD="$OWNER_DB_PASSWORD"
      --from-literal=INTERNAL_TOKEN_KEY="$INTERNAL_TOKEN_KEY")
  seal cartogra gateway-secrets "${DB[@]}" \
    --from-literal=JWT_SECRET="$JWT_SECRET" \
    --from-literal=RESEND_API_KEY="$RESEND_API_KEY" \
    --from-literal=GOOGLE_CLIENT_SECRET=unset \
    --from-literal=GITHUB_CLIENT_SECRET=unset \
    --from-literal=BOOTSTRAP_ADMIN_PASSWORD="$ADMIN_PASSWORD"
  seal cartogra registry-secrets "${DB[@]}"
  seal cartogra topology-secrets "${DB[@]}"
  seal cartogra contract-secrets "${DB[@]}"
  seal cartogra ingestion-secrets "${DB[@]}" --from-literal=CLUSTER_CREDENTIALS_KEY="$CLUSTER_CREDENTIALS_KEY"
  seal cartogra postgres-secrets --from-literal=DB_USERNAME=cartogra --from-literal=DB_PASSWORD="$DB_PASSWORD" \
    --from-literal=CARTOGRA_OWNER_PASSWORD="$OWNER_DB_PASSWORD" --from-literal=CARTOGRA_APP_PASSWORD="$APP_DB_PASSWORD"
  run git status --short infra/k8s/sealed/
  note "Commit these files on the RLS branch, so that they merge with the code."
  finished seal
fi

# ──────────────────────────────────────────────────────────────────────────
stage "After the RLS deploy: apply the secrets and restart the services"
if begin deploy; then
  warn "Do not continue before the RLS release runs on production. Old pods break with the new secrets."
  step "If you have not merged the RLS pull request yet, stop here (Ctrl+C) and run this wizard again after the deploy."
  step "Merge the RLS pull request. The images workflow runs, then the deploy workflow starts by itself."
  pause "Press Enter when the deploy workflow succeeded"
  run kubectl -n cartogra get deploy -o 'custom-columns=NAME:.metadata.name,IMAGE:.spec.template.spec.containers[0].image'
  step "Expect the commit of the RLS merge in each image tag."
  confirm "Does each service run the RLS release?" || exit 1
  run kubectl apply -f infra/k8s/sealed/
  note "Spring reads the secrets only at start, so restart the services."
  for d in gateway registry topology contract ingestion; do
    run kubectl -n cartogra rollout restart "deploy/$d"
  done
  for d in gateway registry topology contract ingestion; do
    run kubectl -n cartogra rollout status "deploy/$d" --timeout=5m
  done
  run kubectl -n cartogra get pods
  finished deploy
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Verify"
if begin verify; then
  run kubectl -n cartogra exec postgres-0 -- sh -c \
    'psql -U "$(cat /etc/cartogra/secrets/DB_USERNAME)" -d cartogra -tA -c "select n.nspname || chr(46) || c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.relrowsecurity and c.relforcerowsecurity order by 1"'
  step "Expect each tenant table of registry, topology, ingestion and contract."
  run kubectl -n cartogra exec postgres-0 -- sh -c \
    'psql -U "$(cat /etc/cartogra/secrets/DB_USERNAME)" -d cartogra -tA -c "select usename, count(*) from pg_stat_activity where datname = current_database() group by 1"'
  step "Expect the service connections as cartogra_app, not as the superuser."
  step "Sign in at the site. Open services, the graph, contracts and SCM connections."
  step "Open the guest demo. Each list must show the Acme data."
  pause "Press Enter when all of that works"
  finished verify
fi

finish
printf '\n'
}

run_wizard "$@"; exit
